using SonrisaNews.Shared;

namespace SonrisaNews.Infrastructure.Persistence;

/// <summary>DI helpers for the EF Core context. Call from the API and Worker <c>Program.cs</c>.</summary>
public static class SonrisaNewsDbContextRegistration
{
    /// <summary>Registers the DbContext against SQLite. Connection string is read from <c>ConnectionStrings:Sonrisa</c>.</summary>
    public static IServiceCollection AddSonrisaNewsDbContext(this IServiceCollection services)
    {
        services.AddDbContext<SonrisaNewsDbContext>((sp, options) =>
        {
            var connectionString = sp.GetRequiredService<Microsoft.Extensions.Configuration.IConfiguration>()
                .GetConnectionString(ConfigurationKeys.SonrisaDatabase);

            if (string.IsNullOrWhiteSpace(connectionString))
            {
                throw new InvalidOperationException(
                    $"Missing connection string '{ConfigurationKeys.SonrisaDatabase}' under '{ConfigurationKeys.ConnectionStrings}'.");
            }

            options.UseSqlite(connectionString);
        });

        return services;
    }
}

