// ---------------------------------------------------------------------------
// Implementation
// ---------------------------------------------------------------------------
static async Task<int> AuditAsync(FileInfo policiesFile, DirectoryInfo controllersDir)
{
    if (!policiesFile.Exists)
    {
        Console.Error.WriteLine($"❌ Policies file not found: {policiesFile.FullName}");
        return 2;
    }

    if (!controllersDir.Exists)
    {
        Console.Error.WriteLine($"❌ Controllers directory not found: {controllersDir.FullName}");
        return 2;
    }

    // Wave 1: skeleton. Wave 3 fills in the full Casbin model load + per-policy
    //         grant lookup. The skeleton exists so `dotnet run --project RbacAudit`
    //         exits 0 with no findings on a fresh wave-1 tree (which has no
    //         controllers yet).
    var policyLines = await File.ReadAllLinesAsync(policiesFile.FullName);
    var policyCount = policyLines.Count(line =>
        !string.IsNullOrWhiteSpace(line) && !line.StartsWith('#'));

    Console.WriteLine($"✔  Loaded {policyCount} policy lines from {policiesFile.Name}");
    Console.WriteLine($"✔  Scanned {Directory.GetFiles(controllersDir.FullName, "*.cs", SearchOption.AllDirectories).Length} controller files");
    Console.WriteLine("✔  No findings (skeleton mode — wave 3 wires the full audit).");

    return 0;
}

using FluentAssertions;
using SonrisaNews.Domain;
using Xunit;

namespace SonrisaNews.UnitTests;

public class EnumsTests
{
    [Fact]
    public void AlertType_HasThreeValues()
    {
        // The MVP supports exactly three alert types — News, Market, Disaster.
        // A new type is a deliberate schema change and must add a new enum value
        // + filter schema + matcher. This test guards against accidental drift.
        var values = Enum.GetValues<AlertType>();
        values.Should().HaveCount(3);
        values.Should().Contain(new[] { AlertType.News, AlertType.Market, AlertType.Disaster });
    }

    [Fact]
    public void DeliveryMode_HasFourModes()
    {
        // realtime + 3 digest cadences (15m / hourly / daily).
        Enum.GetValues<DeliveryMode>().Should().HaveCount(4);
    }

    [Fact]
    public void ChannelType_HasTwoImplementationsInMvp()
    {
        // Email + Slack are the only channels implemented in the MVP.
        // The interface is ready for more (SMS, push, webhook), but no others ship yet.
        Enum.GetValues<ChannelType>().Should().HaveCount(2);
    }
}

using FluentAssertions;
using SonrisaNews.Domain;
using Xunit;

namespace SonrisaNews.UnitTests;

public class DomainExceptionTests
{
    [Fact]
    public void Constructor_SetsCodeAndMessage()
    {
        var ex = new DomainException("AlertNotFound", "The alert was not found.");

        ex.Code.Should().Be("AlertNotFound");
        ex.Message.Should().Be("The alert was not found.");
    }

    [Fact]
    public void DomainException_IsAnException()
    {
        // Domain exceptions must be catchable as System.Exception so middleware
        // can route them through the ProblemDetails pipeline.
        var ex = new DomainException("X", "x");
        ex.Should().BeAssignableTo<Exception>();
    }
}

