using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

// --- CLI args ------------------------------------------------------------------
var policiesOption = new Option<FileInfo>(
    "--policies",
    "Path to the rbac_policy.csv file that defines the policy grants.")
{
    IsRequired = true,
};

var controllersOption = new Option<DirectoryInfo>(
    "--controllers",
    "Directory that contains the .cs controllers to audit.")
{
    IsRequired = true,
};

var root = new RootCommand("Audit RBAC usage: every [Authorize(Policy = \"...\")] attribute in the controllers must be granted in the policy file.")
{
    policiesOption,
    controllersOption,
};

root.SetHandler(async (FileInfo policies, DirectoryInfo controllers) =>
{
    var exitCode = await AuditAsync(policies, controllers);
    Environment.Exit(exitCode);
}, policiesOption, controllersOption);

return await root.InvokeAsync(args);


// ---------------------------------------------------------------------------
// Implementation
// ---------------------------------------------------------------------------
static async Task<int> AuditAsync(FileInfo policiesFile, DirectoryInfo controllersDir)
{
    if (!policiesFile.Exists)
    {
        Console.Error.WriteLine($"❌ Policies file not found: {policiesFile.FullName}");
        return 2;
    }

    if (!controllersDir.Exists)
    {
        Console.Error.WriteLine($"❌ Controllers directory not found: {controllersDir.FullName}");
        return 2;
    }

    // Wave 1: skeleton. Wave 3 fills in the full Casbin model load + per-policy
    //         grant lookup. The skeleton exists so `dotnet run --project RbacAudit`
    //         exits 0 with no findings on a fresh wave-1 tree (which has no
    //         controllers yet).
    var policyLines = await File.ReadAllLinesAsync(policiesFile.FullName);
    var policyCount = policyLines.Count(line =>
        !string.IsNullOrWhiteSpace(line) && !line.StartsWith('#'));

    Console.WriteLine($"✔  Loaded {policyCount} policy lines from {policiesFile.Name}");
    Console.WriteLine($"✔  Scanned {Directory.GetFiles(controllersDir.FullName, "*.cs", SearchOption.AllDirectories).Length} controller files");
    Console.WriteLine("✔  No findings (skeleton mode — wave 3 wires the full audit).");

    return 0;
}
"}

