// Aspire 13 picks up the API's own Kestrel endpoint from launchSettings.json,
// so we don't redeclare WithHttpEndpoint here — that would collide. The dashboard
// uses the project's default port (5080) and the Aspire service-discovery side
// uses the internal allocation.

var api = builder.AddProject<Projects.SonrisaNews_Api>("api")
    .WithEnvironment("ASPNETCORE_ENVIRONMENT", "Development");

var worker = builder.AddProject<Projects.SonrisaNews_Worker>("worker")
    .WithEnvironment("DOTNET_ENVIRONMENT", "Development");

// The Python yfinance sidecar runs as a native process (no Docker). The Aspire
// `AddExecutable` resource attaches it to the dashboard so the dev sees its
// stdout, env, and lifecycle. In wave 7 the C# MarketPoller is wired to this
// service via service discovery; the sidecar itself is just a long-lived
// process for now.
var yfinance = builder.AddExecutable(
        name: "yfinance-sidecar",
        command: "uv",
        workingDirectory: "../services/yfinance")
    .WithArgs("run", "uvicorn", "yfinance_service.main:create_app", "--factory", "--port", "8001")
    .WithHttpEndpoint(port: 8001, name: "http")
    .WithEnvironment("YF__ENVIRONMENT", "Development");

