// uses the internal allocation.

var api = builder.AddProject<Projects.SonrisaNews_Api>("api")
    .WithEnvironment("ASPNETCORE_ENVIRONMENT", "Development");

var worker = builder.AddProject<Projects.SonrisaNews_Worker>("worker")
    .WithEnvironment("DOTNET_ENVIRONMENT", "Development");

// The Python yfinance sidecar runs as a native process (no Docker). The Aspire
// `AddExecutable` resource attaches it to the dashboard so the dev sees its
// stdout, env, and lifecycle. In wave 7 the C# MarketPoller is wired to this
